def Q(q, key, d, yn=False): return P(q, key, list(d), yn)
def tb(tid, old, new, tail):
    s = SRC[tid]; assert old in s, (tid, old); return re.sub(r" {2,}", " ", (s.replace(old, new).strip() + " " + tail).strip())

